export const getSchedule = async (sport: string, forceRefresh = false): Promise<Game[]> => {
  // Check Cache
  const todayKey = new Date().toDateString();
  const cacheKey = `${sport}-${todayKey}`;

  if (!forceRefresh && scheduleCache[cacheKey] && (Date.now() - scheduleCache[cacheKey].timestamp < CACHE_DURATION)) {
    return scheduleCache[cacheKey].data;
  }

  const ai = getAI();
  const today = new Date().toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric' });

  const prompt = `
  Perform a real-time data retrieval for active/upcoming ${sport} games on ${today}.

  ACTIONS:
  1. Search for the confirmed game schedule.
  2. CRITICAL: Search for the LATEST CONSENSUS BETTING ODDS (Spread, Moneyline, Total) from major sportsbooks.
  3. If a game is currently LIVE (in progress), fetch the real-time score and LIVE adjusted odds if available.

  RETURN FORMAT:
  Return a VALID JSON object matching the schema. 
  - Ensure 'status' is correct ('Scheduled', 'Live', 'Finished').
  - Populate 'odds' with the consensus numbers. Use 'Even' or '-' if unavailable.
  `;

  try {
    const response = await callWithRetry(async () => {
      // Create a new instance per call to ensure fresh configuration
      return await ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: { 
          tools: [{ googleSearch: {} }],
          responseMimeType: 'application/json',
          responseSchema: scheduleSchema 
        }
      });
    });

    const data = JSON.parse(response.text || '{}');
    const games = data.games || [];

    // Update Cache
    scheduleCache[cacheKey] = { data: games, timestamp: Date.now() };

    return games;
  } catch (error: any) {
    console.warn("Alpha schedule sync failed (Cached/Empty fallback):", error.message);
    if (scheduleCache[cacheKey]) {
        return scheduleCache[cacheKey].data;
    }
    throw error;
  }
};

export const generatePrediction = async (home: string, away: string, systemInstruction: string): Promise<Prediction> => {
    const ai = getAI();
    // Supernatural Logic: "Veto & Validate" Protocol + Protocol 80 (Sharp Action)
    const prompt = `
    ACTIVATE "SUPERNATURAL ACCURACY" PROTOCOL FOR ${home} vs ${away}.
    OBJECTIVE: IDENTIFY THE HIGHEST POSSIBILITY OUTCOME (THE "BEST BET").

    PHASE 1: THE VETO CHECK (CRITICAL)
    You MUST first perform a specific Google Search for:
    1. "${home} injury report today late scratch"
    2. "${away} injury report today late scratch"
    3. "Referee assignment ${home} vs ${away} tendencies"

    PHASE 2: PROTOCOL 80 (MARKET PSYCHOLOGY & LIVE ODDS)
    Perform a search for "Live betting odds ${home} vs ${away} opening vs current" and "Betting splits public vs sharp".
    - EXTRACT THE CURRENT LIVE ODDS vs OPENING LINES.
    - IDENTIFY REVERSE LINE MOVEMENT (RLM): If >65% of bets are on one side, but the line moved AGAINST them (e.g. Open -3, Current -2.5), that is Sharp Money.
    - TRAP DETECTION: If a top-tier team is playing a low-tier team and the spread is suspiciously small (e.g., -2.5), flag as a TRAP.
    - Populate 'syndicateIntel' and 'trapDetection' fields with this data.

    PHASE 3: THE SYNDICATE SIMULATION
    Simulate three distinct expert personas to derive the truth:
    A) THE QUANT: Pure efficiency metrics, pace, effective field goal %. No emotion.
    B) THE SHARP: Tracks "Smart Money". Values RLM and fading the public.
    C) THE SCOUT: Psychological factors (Scandals, Motivation, Revenge).

    PHASE 4: EXECUTION & BEST BET ISOLATION
    - Combine these into 'ensembleModel'.
    - CALCULATE THE SINGLE HIGHEST PROBABILITY OUTCOME. 
    - This is the 'bestBet'. It can be the Winner, the Spread, the Total, OR a Player Prop.
    - Compare implied probability of odds vs your calculated probability to find the 'Edge'.
    - If "Sharp" and "Quant" disagree, favor the "Sharp" (Vegas knows best).
    - Calculate 'entropyScore' (0-20=Lock, 80-100=Chaos).

    OUTPUT:
    Return a JSON response adhering strictly to the schema. 
    Ensure the 'bestBet' field is populated with the strongest statistical signal.
    `;

    return await callWithRetry(async () => {
        const response = await ai.models.generateContent({
            model: 'gemini-3-pro-preview',
            contents: prompt,
            config: {
                systemInstruction: systemInstruction,
                responseSchema: predictionSchema,
                responseMimeType: 'application/json',
                thinkingConfig: { thinkingBudget: 32768 },
                tools: [{ googleSearch: {} }]
            }
        });

        const cleanText = response.text?.replace(/```json\n?|```/g, '').trim();
        if (!cleanText) throw new Error("Received empty neural response signal.");

        return JSON.parse(cleanText);
    });
};

