export const GameSchedule: React.FC<GameScheduleProps> = memo(({ sport, selectedGame, onSelectGame, oddsFormat = 'American' }) => {
  const [games, setGames] = useState<Game[]>([]);
  const [isLoading, setIsLoading] = useState<boolean>(false);
  const [isRefreshing, setIsRefreshing] = useState<boolean>(false);
  const [error, setError] = useState<string | null>(null);
  const [isQuotaError, setIsQuotaError] = useState<boolean>(false);
  const [loadMsgIdx, setLoadMsgIdx] = useState(0);
  const [lastUpdated, setLastUpdated] = useState<Date>(new Date());
  const [retryCooldown, setRetryCooldown] = useState<number>(0);

  const fetchGames = useCallback(async (quiet = false, forceRefresh = false) => {
    if (retryCooldown > 0 && forceRefresh) return;

    if (!quiet) setIsLoading(true);
    else setIsRefreshing(true);

    setError(null);
    setIsQuotaError(false);
    try {
      const fetchedGames = await getSchedule(sport, forceRefresh);
      if (fetchedGames && fetchedGames.length > 0) {
        setGames(fetchedGames);
        setLastUpdated(new Date());
      } else if (!quiet) {
        setError(`No active ${sport} markets found in current data stream.`);
      }
    } catch (err: any) {
      const isQuota = err.status === 429 || JSON.stringify(err).includes("429") || JSON.stringify(err).includes("RESOURCE_EXHAUSTED");
      if (isQuota) {
        setIsQuotaError(true);
        setError("Neural Bandwidth Restricted: Quota Limit Reached. Engine is cooling down.");
        setRetryCooldown(45); // Cooldown for 45s
      } else if (!quiet) {
        setError('Satellite link lost. Engine cannot reach market data.');
      }
    } finally {
      setIsLoading(false);
      setIsRefreshing(false);
    }
  }, [sport, retryCooldown]);

  useEffect(() => {
    fetchGames();
    const interval = setInterval(() => setLoadMsgIdx(prev => (prev + 1) % LOAD_SUB_MESSAGES.length), 2000);
    return () => clearInterval(interval);
  }, [fetchGames]);

  // Cooldown timer
  useEffect(() => {
    if (retryCooldown > 0) {
      const timer = setInterval(() => setRetryCooldown(prev => prev - 1), 1000);
      return () => clearInterval(timer);
    }
  }, [retryCooldown]);

  return (
    <div className="w-full max-w-7xl mx-auto space-y-6">
       <div className="flex items-center justify-between px-4">
          <div className="flex items-center gap-4">
             <div className="w-10 h-10 rounded-xl bg-zinc-900 flex items-center justify-center border border-zinc-800">
                <AnalyticsIcon className="w-5 h-5 text-zinc-500" />
             </div>
             <div>
                <h3 className="text-xl font-black text-white uppercase italic tracking-tighter">Live Market Feed</h3>
                <div className="flex items-center gap-2">
                    <span className="text-[9px] font-black text-zinc-500 uppercase tracking-widest">{sport} PROTOCOL ACTIVE</span>
                    <span className="text-[9px] text-zinc-600">•</span>
                    <span className="text-[9px] text-zinc-600">Updated: {lastUpdated.toLocaleTimeString()}</span>
                </div>
             </div>
          </div>

          <button 
             onClick={() => fetchGames(true, true)}
             disabled={isRefreshing || retryCooldown > 0}
             className={`flex items-center gap-2 px-4 py-2 rounded-xl text-[10px] font-black uppercase tracking-widest transition-all ${
                 isRefreshing 
                 ? 'bg-amber-500/20 text-amber-500 cursor-wait' 
                 : retryCooldown > 0
                   ? 'bg-zinc-800 text-zinc-600 cursor-not-allowed'
                   : 'bg-zinc-900 text-zinc-400 hover:text-white hover:bg-zinc-800'
             }`}
          >
             <div className={`w-1.5 h-1.5 rounded-full ${isRefreshing ? 'bg-amber-500 animate-ping' : 'bg-green-500'}`}></div>
             {isRefreshing ? 'Syncing...' : retryCooldown > 0 ? `Cooling Down (${retryCooldown}s)` : 'Sync Live Odds'}
          </button>
       </div>

       {error ? (
          <div className="p-8 rounded-[2.5rem] bg-red-950/10 border border-red-500/20 text-center space-y-4">
             <div className="w-12 h-12 rounded-full bg-red-500/10 flex items-center justify-center mx-auto mb-2">
                <svg className="w-6 h-6 text-red-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" /></svg>
             </div>
             <p className="text-red-400 font-bold text-sm uppercase tracking-widest">{error}</p>
             {!isQuotaError && (
                 <button onClick={() => fetchGames(false, true)} className="text-[10px] font-black text-red-500 uppercase tracking-widest border-b border-red-500/50 hover:text-white hover:border-white transition-colors">
                    Retry Connection
                 </button>
             )}
          </div>
       ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6 animate-fade-in">
             {games.map((game) => (
                <GameCard 
                    key={game.id} 
                    game={game} 
                    isSelected={selectedGame?.id === game.id} 
                    onSelectGame={onSelectGame} 
                    oddsFormat={oddsFormat}
                />
             ))}
          </div>
       )}
    </div>
  );
});

